output:
{
  "world_id": "wld_velisara",
  "name": "Velisara, the Drifting Crown",
  "description": "Velisara is an archipelago of floating islands, each carrying its own weather, customs, and stubborn claim to independence. Ancient skybridges span the blue distances between them, their pale stone ribs humming when the wind turns. A young mapmaker finds that the bridges are failing—not from age alone, but because their makers anchored them to the islands' remembered positions, and the islands have begun to forget. To keep the realm from drifting apart, rival enclaves must share their maps, their histories, and the one truth each has tried to leave off the page.",
  "locations": [
    {
      "id": "loc_aevenreach",
      "name": "Aevenreach",
      "description": "A high, green island of terraced orchards and observatory towers. Its mapmakers chart not only coastlines but the changing shadows of neighboring islands, believing a place is safest when someone remembers where it belongs."
    },
    {
      "id": "loc_morrowmere",
      "name": "Morrowmere",
      "description": "A crescent island whose lakes spill in silver veils over the rim, turning to mist before they fall far. Its bellkeepers listen for the skybridge's answering tones and have begun to hear gaps where a note should be."
    },
    {
      "id": "loc_cinderwake",
      "name": "Cinderwake",
      "description": "A dark, warm island wrapped around a field of glassy vents. Its careful engineers mend bridge joints with braided crystal and insist that practical repairs matter more than old songs."
    },
    {
      "id": "loc_liltmarket",
      "name": "Liltmarket",
      "description": "A small island that circles a slow-moving cloudbank, crowded with floating stalls, wind gardens, and guesthouses. Traders from every enclave meet here, though the market's shifting paths make it difficult to tell who has arrived and who has quietly left."
    }
  ],
  "factions": [
    {
      "id": "fac_inkwardens",
      "name": "The Inkwardens",
      "description": "Mapmakers and record-keepers of Aevenreach who preserve each island's old position in layered charts. They want the enclaves to reveal their full histories, including the disputed names of the first bridge builders.",
      "location_ids": [
        "loc_aevenreach"
      ]
    },
    {
      "id": "fac_bellkeepers",
      "name": "The Bellkeepers",
      "description": "Morrowmere's listeners, who maintain tuned bells along the bridge approaches. They believe every island has a true note and that a bridge can be steadied when its connected communities answer in harmony.",
      "location_ids": [
        "loc_morrowmere"
      ]
    },
    {
      "id": "fac_crystalwrights",
      "name": "The Crystalwrights",
      "description": "Cinderwake's engineers, who build precise crystal braces for failing bridge spans. They favor measurable fixes and distrust any plan that relies on memory, ceremony, or political promises.",
      "location_ids": [
        "loc_cinderwake"
      ]
    },
    {
      "id": "fac_tideledger",
      "name": "The Tideledger Compact",
      "description": "Liltmarket's traders, who keep a shared ledger of arrivals, routes, and favors owed. They can bring rival leaders to the same table, but some members profit when routes become scarce.",
      "location_ids": [
        "loc_liltmarket"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_anchor_memory",
      "statement": "A skybridge remains aligned only while the islands it joins are remembered in a mutually acknowledged account of their former positions.",
      "category": "metaphysics"
    },
    {
      "id": "rul_tone_strain",
      "statement": "When a bridge's supporting notes fall out of tune, its stone grows lighter and its span begins to wander.",
      "category": "physics"
    },
    {
      "id": "rul_shared_passage",
      "statement": "No enclave may close a skybridge without first warning every community that depends on its route.",
      "category": "social"
    },
    {
      "id": "rul_crystal_brace",
      "statement": "Crystal braces can slow a bridge's drift, but cannot restore an alignment whose shared history has been lost.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_first_measure",
      "name": "The First Measure",
      "description": "The early island communities set their distances by singing each other's names across the open sky. Their shared verses gave the first skybridges a steady course.",
      "era": "Before the Enclaves",
      "location_ids": [
        "loc_aevenreach",
        "loc_morrowmere"
      ]
    },
    {
      "id": "evt_silent_revision",
      "name": "The Silent Revision",
      "description": "During a bitter dispute, the founding account was altered and one island's name was removed. The bridges held, but their notes changed, and the communities began to disagree about where the islands had once stood.",
      "era": "The Years of Division",
      "location_ids": [
        "loc_aevenreach",
        "loc_cinderwake"
      ]
    },
    {
      "id": "evt_market_compact",
      "name": "The Market Compact",
      "description": "Liltmarket's traders established a common route ledger after several drifting islands lost contact. The compact reunited trade, but its private copies of old routes left one group with unusual influence.",
      "era": "The Compact Years",
      "location_ids": [
        "loc_liltmarket",
        "loc_morrowmere"
      ]
    },
    {
      "id": "evt_missing_note",
      "name": "The Missing Note",
      "description": "The Bellkeepers heard a familiar bridge tone vanish in the night. By dawn, the span toward Cinderwake had shifted, and a fresh mark appeared on an old map that no living cartographer remembered drawing.",
      "era": "Present Day",
      "location_ids": [
        "loc_morrowmere",
        "loc_cinderwake",
        "loc_aevenreach"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_map_or_metal",
      "name": "Map or Metal",
      "description": "The Inkwardens and Crystalwrights disagree over the failing spans: one side wants a shared, honest account of the past, while the other races to brace the bridges before another island drifts away. Each delay risks lives; each rushed repair may conceal the cause.",
      "faction_ids": [
        "fac_inkwardens",
        "fac_crystalwrights"
      ]
    },
    {
      "id": "cnf_the_unwritten_route",
      "name": "The Unwritten Route",
      "description": "The Tideledger Compact holds an old route that could reconnect the divided enclaves, but disclosing it may expose who benefited from the earlier revision. The Bellkeepers need that route to restore the bridge chorus, while the Compact fears losing its leverage.",
      "faction_ids": [
        "fac_tideledger",
        "fac_bellkeepers"
      ]
    }
  ]
}
